script.inlineScript:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  let libraries = api.data.deduplication_template_get_all_libraries.output.result;
	return libraries[0].id;
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return [
    {
      label: helpers.translateSync("Template count"), 
      value: {
        type: "string", 
        value: api.state.templateCount
      }
    }, 
    {
      label: helpers.translateSync("Templates running"), 
      value: {
        type: "string", 
        value: api.state.templateRunningCount
      }
    }
  ];
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return api.state.template.state == 'published';
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return api.state.template.state == 'draft' || api.state.template.state == 'retired';
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return api.state.template.state === 'published' || api.state.template.state === 'retired';
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  if(api.state.template.state == 'published'){
    return helpers.translateSync('Published template is not editable. Unpublish it to edit.');
  }else{
	return helpers.translateSync('Edit template');
  }
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return api.state.template.state === 'published';
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return [
    {
      label: helpers.translateSync("State"), 
      value: api.state.template.stateDisplayValue
    }
  ];
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return api.state.template.name + ' will be published and be available for use.';
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return api.state.template.name + " will be unpublished and won't be available for use.";
}
